fast_pseudocode:
# YBLOCK must be multiple of 3 (the channel stride); do NOT use power-of-2 YBLOCK
# Keep autotune config set small to avoid large dynamic smem overhead
@triton.autotune(configs=[
    Config({'XBLOCK':256,'YBLOCK':4},  num_warps=4),  # original small set
    Config({'XBLOCK':128,'YBLOCK':8},  num_warps=4),
    # OR use YBLOCK in {3,6,15,30} if adding new configs
], key=['ynumel','xnumel'])
@triton.jit
def kernel(...):
    tl.store(out_ptr + (y0 + 3*x2 + 150528*y1), val, mask)

